use serde::{Deserialize,Serialize}; use super::{error::{AdmissionError,AdmissionErrorKind,Result},subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)] pub enum ExclusionState{Open,Excluded{reason:String,at_epoch:u64},Reentered{reason:String,at_epoch:u64}}
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct Exclusion{pub subject:SubjectId,pub state:ExclusionState}
impl Exclusion{pub fn open(subject:SubjectId)->Self{Self{subject,state:ExclusionState::Open}}pub fn exclude(&mut self,reason:impl Into<String>,epoch:u64)->Result<()>{match self.state{ExclusionState::Open|ExclusionState::Reentered{..}=>{self.state=ExclusionState::Excluded{reason:reason.into(),at_epoch:epoch};Ok(())},ExclusionState::Excluded{..}=>Err(AdmissionError::new(AdmissionErrorKind::Excluded,"exclusion.already","subject already excluded").subject(self.subject.key()))}}pub fn reenter(&mut self,reason:impl Into<String>,epoch:u64,authorized:bool)->Result<()>{if !authorized{return Err(AdmissionError::new(AdmissionErrorKind::AuthorityDenied,"exclusion.reentry.denied","re-entry requires explicit authority").subject(self.subject.key()))}match self.state{ExclusionState::Excluded{..}=>{self.state=ExclusionState::Reentered{reason:reason.into(),at_epoch:epoch};Ok(())},_=>Err(AdmissionError::new(AdmissionErrorKind::Excluded,"exclusion.reentry.invalid","only excluded subjects may re-enter").subject(self.subject.key()))}}pub fn require_open(&self)->Result<()>{if matches!(self.state,ExclusionState::Excluded{..}){Err(AdmissionError::new(AdmissionErrorKind::Excluded,"subject.excluded","subject is excluded").subject(self.subject.key()))}else{Ok(())}}}